<script setup lang="ts">
import {previewPrint} from './printPreview';
import UiIcon from './UiIcon.vue';
import {can} from './api';
const props=defineProps<{columns:{key:string;label:string;digits?:number}[];rows:{tankId:string;pinned?:boolean;cells:Record<string,string|number|null>}[];licensed:boolean;admin?:boolean;busy?:boolean;serverAt:string|null}>(),emit=defineEmits<{detail:[string];pin:[string]}>();
function display(v:string|number|null|undefined,digits?:number){return v===null||v===undefined?'—':typeof v==='number'?v.toLocaleString('zh-CN',{minimumFractionDigits:digits??0,maximumFractionDigits:digits??6}):v}
function exportRows(){if(!props.licensed||!can('DataExport'))return;window.LocalWorkbook.download('罐清单当前数据',[{name:'罐清单',rows:[['软件生成时间',props.serverAt?new Date(props.serverAt).toLocaleString('zh-CN',{hour12:false}):''],props.columns.map(c=>c.label),...props.rows.map(r=>props.columns.map(c=>r.cells[c.key]??''))]}])}
function print(){if(!props.licensed||!can('DataExport'))return;previewPrint({title:'罐清单当前数据',scope:['当前筛选 '+props.rows.length+' 罐 · 隐藏罐不列入','采集后台时间 '+(props.serverAt?new Date(props.serverAt).toLocaleString('zh-CN',{hour12:false}):'—')],sections:[{title:'当前清单',headers:props.columns.map(c=>c.label),rows:props.rows.map(r=>props.columns.map(c=>display(r.cells[c.key],c.digits)))}]})}
</script>
<template><section class="panel current-readings"><div class="print-only print-heading"><h1>罐清单当前数据</h1><p>{{serverAt?new Date(serverAt).toLocaleString('zh-CN',{hour12:false}):''}} · {{rows.length}}罐 · 使用当前筛选范围</p></div><div class="toolbar"><span>当前筛选 {{rows.length}} 罐 · 含各值状态，隐藏罐不列入</span><div class="inline-actions"><button class="button" :disabled="!licensed||!can('DataExport')||!rows.length" :data-export-allowed="can('DataExport')" @click="can('DataExport')&&exportRows()">导出当前罐清单</button><button class="button" :disabled="!licensed||!can('DataExport')||!rows.length" @click="print">打印预览</button></div></div><div class="table-wrap"><table><thead><tr><th v-for="c in columns" :key="c.key">{{c.label}}</th><th class="screen-only">操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.tankId"><td v-for="c in columns" :key="c.key">{{display(r.cells[c.key],c.digits)}}</td><td class="screen-only reading-row-actions"><button v-if="admin" class="pin-button" :class="{pinned:r.pinned}" :disabled="busy" :aria-label="String(r.cells.code)+(r.pinned?'取消置顶':'置顶')" @click="emit('pin',r.tankId)"><UiIcon name="pin"/>{{r.pinned?'取消置顶':'置顶'}}</button><button class="text-button" @click="emit('detail',r.tankId)">详情</button></td></tr><tr v-if="!rows.length"><td :colspan="columns.length+1" class="empty">当前筛选没有储罐</td></tr></tbody></table></div><p class="table-foot">无效/过期值不填0；冻结液面和上次任务平均温度保留原依据与时间，不充当新的测量。打印与导出沿用当前筛选。</p></section></template>
